    b = False
    while not b:
        n = input("Donner le numéro: ")
        b = len(n) == 15
    return n


def LUHN(n):
    S = 0
    for i in range(len(n)):
        if (i + 1) % 2 == 0:
            a = int(n[i]) * 2
            if a >= 10:
                b = a % 10 + a // 10
                S = S + b
            else:
                S += a
        else:
            S += int(n[i])
    return S


def IMEI(S):
    if S % 10 == 0:
        print("numéro IMEI")
    else:
        print("numéro non IMEI")


